// And groups predicates with the AND operator between them.
func And(predicates ...predicate.Producer) predicate.Producer {
	return predicate.Producer(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.Producer) predicate.Producer {
	return predicate.Producer(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.Producer) predicate.Producer {
	return predicate.Producer(sql.NotPredicates(p))
}
